/// <summary>
/// Data contract for AVADAIReportExportWork cleanup batch job
/// Provides query-based date range selection for cleanup operations
/// </summary>
[DataContractAttribute]
class AVADAIReportExportWorkCleanUpDataContract extends SysOperationDataContractBase
{
    str queryString;
}

Method.Source:
/// <summary>
/// Gets or sets the query string for filtering AVADAIReportExportTable records
/// Uses the AOT query AVADAIReportExportWorkCleanUpQuery as the base
/// </summary>
/// <param name="_queryString">Query string in XML format</param>
/// <returns>The query string</returns>
[DataMemberAttribute, AifQueryTypeAttribute('_queryString', queryStr(AVADAIReportExportWorkCleanUpQuery))]
public str parmQueryString(str _queryString = queryString)
{
    queryString = _queryString;
    return queryString;
}

/// <summary>
/// Gets the query object for filtering records based on the stored query string
/// If no custom query is set, returns the default AOT query
/// </summary>
/// <returns>Query object configured for AVADAIReportExportTable</returns>
public Query getQuery()
{
    if (queryString)
    {
        return new Query(SysOperationHelper::base64Decode(queryString));
    }
    else
    {
        // Return the AOT query as default
        return new Query(queryStr(AVADAIReportExportWorkCleanUpQuery));
    }
}

/// <summary>
/// Sets the query from a Query object
/// </summary>
/// <param name="_query">Query object to store</param>
public void setQuery(Query _query)
{
    queryString = SysOperationHelper::base64Encode(_query.pack());
}
